/* Look up a verified artwork entry and prove the module's own URL agrees
   with the audited bucket path — a mismatch throws at build time, so a
   wrong image can never ship. fullUrl is what the module already renders
   (its own BASE + img); the entry supplies the TRUE pixel dimensions. */
export function artFor(key,fullUrl){
 const a=ART[key];
 if(!a)throw new Error('adventure-dims: unmapped artwork '+key);
 if(!fullUrl||!fullUrl.endsWith(a.img))throw new Error('adventure-dims: URL mismatch for '+key+': '+fullUrl+' does not carry '+a.img);
 return a;
}
